    raw: "各学院（部）：2026-2027学年本科生转专业工作即将启动，各学院在转专业工作启动前应依据《安徽农业大学本科学生转专业办法》（校教发〔2024〕23 号）文件（附件1），成立各学院转专业工作领导小组，拟定转专业选录细则（附件2）。本学年转专业工作，将在新本科教务系统中采用线上申请、审核、录取等方式进行。各学院需分别报送转出学院初审（线上系统关联为申请转专业学生的辅导员）和终审人员名单、转入学院初审和终审人员名单（具体格式见附件3）。各学院于11月3日前报送工作领导小组名单和转出转入初审终审人员名单，11月6日前报送选录细则。纸质版签字盖章报至本科生院学籍管理部门（勤政楼127室），电子版发送至邮箱XueJiKe@ahau.edu.cn，同时将选录细则录入新教务系统转专业模块中（具体录入时间另行通知，线上录入操作手册见附件4）。联系人：赵老师、胡老师；联系电话：0551-65786163。本科生院 2026年10月26日",
