    raw: "各学院、校直单位：为深化我校教育教学改革，充分调动学生学习的积极性、主动性，根据《安徽农业大学本科学生转专业办法》（校教发〔2024〕23 号）（附件1）文件和《2025-2026学年本科生转专业工作安排的通知》精神，对照安徽农业大学2025-2026学年转专业选录细则（附件2），现将2025-2026学年本科生转专业工作安排通知如下：一、申请及审核方式 本次转专业采用线上方式进行。学生个人线上申请，转出转入学院可采用线上线下相结合的方式进行审核，审核后线上录入结果，部分纸质材料线下报送。二、工作安排 1、2025年12月8日8：00-12月11日17:00前，学生线上填写转专业申请表（网址超链接），具体流程见线上申请指南操作（附件3）。2、2025年12月8日8：00-12月12日17：00前，初审及终审人员完成转出审核，具体流程见审核人员线上操作指南（附件4）。待转出学院审核结束，学生个人打印申请表确认签字后于12月15日17:00前递交至所在学院（转出学院）负责转专业工作的老师。3、2025年12月16日17:00前，各学院领导小组审核报送转出申请名单（从系统中导出转出学生申请汇总表）签字盖章后报送至教务处学籍科。4、2025年12月17日8：00-12月24日17：00前，各转入学院系统审核，组织转专业第一志愿选录工作，报送第一志愿拟接收学生名单至教务处学籍科，同时在转专业系统中录入第一志愿选录结果。5、2025年12月26日前，教务处公示第一志愿转专业拟接收学生名单。6、2025年12月29日17:00前，各学院报送第二志愿符合条件的拟转出学生名单（从系统中导出转出学生申请汇总表）。7、2025年12月30日8：00-2026年1月2日17:00前，各转入学院审核报送第二志愿拟接收学生名单至教务处学籍科。8、2026年1月6日前，教务处公示第二志愿转专业拟接收学生名单，同时在转专业系统中录入第二志愿选录结果。9、2026年1月16日前，校长办公会研究决定转专业学生人选。三、相关说明 1、学生线上提交转专业申请后，转出转入学院审批在“数智安农”—“我的待办”栏。四、工作要求 3、申请转专业的学生应修完本学期所选全部课程并参加课程考试。缺考作零分成绩，记录不删除。五、咨询联系 1、转专业政策咨询：学籍科联系人：赵老师、胡老师，联系电话：0551-65786163，地点：勤政楼127室；2、转专业课程学分及成绩咨询：教学信息科联系人：杨老师、李老师，联系电话：0551-65786169，地点：勤政楼122室。教务处 2025年12月4日",
    digestOne: "上一年转专业的完整流程：12月8-11日线上申请，两级审核后按第一、第二志愿分别选录，次年1月16日前校长办公会定人选。",
